/* Tech Robòtica · unitat 6 «Control intel·ligent» (variables, comptadors, calcula, control proporcional, segueix el líder i el cotxe autònom) */
Object.assign(TBADGE, {
  k_variable: { id: 'k_variable', ico: '📦', n: 'Guardià/ana de variables|Guardián/a de variables', d: "Has fet servir variables per canviar la velocitat del robot i per comptar.|Has usado variables para cambiar la velocidad del robot y para contar." },
  k_prop: { id: 'k_prop', ico: '🎚️', n: 'Control proporcional|Control proporcional', d: "Has fet que el robot frenés suau: com més a prop, més a poc a poc.|Has hecho que el robot frenara suave: cuanto más cerca, más despacio." },
  k_lider: { id: 'k_lider', ico: '🚗', n: 'Seguidor/a del líder|Seguidor/a del líder', d: "Has programat un robot que segueix un altre robot sense xocar i sense quedar-se enrere.|Has programado un robot que sigue a otro robot sin chocar y sin quedarse atrás." },
  k_autonom: { id: 'k_autonom', ico: '🚘', n: 'Enginyer/a del cotxe autònom|Ingeniero/a del coche autónomo', d: "Projecte acabat: un cotxe que segueix la carretera, guarda la distància, frena amb llums i encén els fars de nit.|Proyecto terminado: un coche que sigue la carretera, guarda la distancia, frena con luces y enciende los faros de noche." }
});
ROBOTICA_UNITS[6] = { t: 'Control intel·ligent|Control inteligente', d: 'Variables, control proporcional i cotxes autònoms|Variables, control proporcional y coches autónomos', color: '#0FA3A3', s: [
  /* ---------- Sessió 1 · Velocitat que canvia (variables i comptadors) ---------- */
  { id: 'k6-1', t: 'Velocitat que canvia|Velocidad que cambia', min: 45, badge: 'k_variable',
    learn: ["Una variable guarda un número amb un nom (velocitat, comptador…) que el programa llegeix i canvia mentre funciona.|Una variable guarda un número con un nombre (velocidad, contador…) que el programa lee y cambia mientras funciona.",
      "«Posa» substitueix el número de la capsa; «canvia en» n'hi suma (o resta) un altre.|«Pon» sustituye el número de la caja; «cambia en» le suma (o resta) otro.",
      "Un comptador és una variable que comença a 0 i suma 1 cada vegada que passa una cosa, només una vegada per cosa.|Un contador es una variable que empieza en 0 y suma 1 cada vez que pasa algo, solo una vez por cosa."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "Des de la unitat 1 ho saps: si poses els motors a velocitat <b>20</b>, què fa el Maqueen?|Desde la unidad 1 lo sabes: si pones los motores a velocidad <b>20</b>, ¿qué hace el Maqueen?",
        opts: ["No es mou: per sota de ~30 el motor no té prou força|No se mueve: por debajo de ~30 el motor no tiene fuerza suficiente", "Va molt a poc a poc, a 20 cm cada segon|Va muy despacio, a 20 cm cada segundo", "Va enrere|Va hacia atrás"], a: 0,
        ex: "És la <b>zona morta</b>. Avui hi tornarem a pensar, perquè la velocitat canviarà mentre el programa funciona.|Es la <b>zona muerta</b>. Hoy volveremos a pensar en ella, porque la velocidad cambiará mientras el programa funciona." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'lab', title: 'El Lab de Mobilitat|El Lab de Movilidad',
        t: "Benvingut/da al <b>Lab de Mobilitat</b>, on s'inventen vehicles que es condueixen sols! Primera feina: portar <b>ous</b> al forn. Ahir el robot va arrencar de cop a 255… i els ous van sortir volant! Avui faràs servir <b>variables</b> perquè arrenqui suau i per <b>comptar</b>.|¡Bienvenido/a al <b>Lab de Movilidad</b>, donde se inventan vehículos que se conducen solos! Primer trabajo: llevar <b>huevos</b> al horno. Ayer el robot arrancó de golpe a 255… ¡y los huevos salieron volando! Hoy usarás <b>variables</b> para que arranque suave y para <b>contar</b>." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Recorda|Recuerda', t: 'Recorda: la variable|Recuerda: la variable', anim: 'k6var',
          x: "<b>Recorda:</b> una <span class='hl'>variable</span> guarda un número amb un nom, com <b>velocitat</b>. El robot el pot llegir i canviar mentre el programa funciona.|<b>Recuerda:</b> una <span class='hl'>variable</span> guarda un número con un nombre, como <b>velocidad</b>. El robot lo puede leer y cambiar mientras el programa funciona.",
          tip: "Tria noms que expliquin què guarden: «velocitat», «comptador»… Així el programa s'entén sol.|Elige nombres que expliquen qué guardan: «velocidad», «contador»… Así el programa se entiende solo." },
        { k: 'Posa i canvia|Pon y cambia', t: "L'arrencada suau|El arranque suave",
          robo: { w: { w: 130, h: 40, bot: [12, 20, 90] }, prog: 'start{ set:vel,40 rep:6{ run:all,fwd,$vel wait:500 change:vel,30 } stop:all }', varNames: { vel: 'velocitat|velocidad' } },
          x: "<b>Posa velocitat a 40</b> omple la capsa. Dins del «repeteix», el motor fa servir <b>el número de la capsa</b> i <b>canvia velocitat en 30</b> hi suma 30: 40, 70, 100, 130… Cada tros del rastre és més llarg perquè el robot va cada cop més de pressa.|<b>Pon velocidad a 40</b> llena la caja. Dentro del «repite», el motor usa <b>el número de la caja</b> y <b>cambia velocidad en 30</b> le suma 30: 40, 70, 100, 130… Cada trozo del rastro es más largo porque el robot va cada vez más deprisa.",
          tip: "La velocitat del motor pot ser un número o una variable: toca el camp de velocitat i tria la variable.|La velocidad del motor puede ser un número o una variable: toca el campo de velocidad y elige la variable." },
        { k: 'Compte!|¡Cuidado!', t: "«Posa» no és «canvia»|«Pon» no es «cambia»",
          robo: { w: { w: 130, h: 40, bot: [12, 20, 90] }, prog: 'start{ rep:6{ set:vel,40 run:all,fwd,$vel wait:500 change:vel,30 } stop:all }', varNames: { vel: 'velocitat|velocidad' } },
          x: "Aquí el «posa velocitat a 40» és <b>dins</b> del «repeteix»: a cada volta la capsa torna a 40 i el robot no accelera mai.|Aquí el «pon velocidad a 40» está <b>dentro</b> del «repite»: en cada vuelta la caja vuelve a 40 y el robot no acelera nunca.",
          bad: "«Posa velocitat a 40» suma 40 a la velocitat.|«Pon velocidad a 40» suma 40 a la velocidad.", good: "«Posa» substitueix el número; «canvia en» és el que suma.|«Pon» sustituye el número; «cambia en» es el que suma." },
        { k: 'Comptador|Contador', t: 'Comptar amb una variable|Contar con una variable', anim: 'k6count',
          x: "Un <span class='hl'>comptador</span> és una variable que comença a <b>0</b> i fa <b>canvia comptador en 1</b> cada vegada que passa alguna cosa: una línia, un obstacle, una volta… Així el robot pot decidir: «para quan comptador = 3».|Un <span class='hl'>contador</span> es una variable que empieza en <b>0</b> y hace <b>cambia contador en 1</b> cada vez que pasa algo: una línea, un obstáculo, una vuelta… Así el robot puede decidir: «para cuando contador = 3».",
          tip: "Abans de començar, posa el comptador a 0: si no, podria guardar un número d'abans.|Antes de empezar, pon el contador a 0: si no, podría guardar un número de antes." },
        { k: 'Mira-ho|Míralo', t: 'Compta els passos de vianants|Cuenta los pasos de cebra',
          robo: { w: { w: 150, h: 40, bot: [12, 20, 90], lines: [{ p: [[35, 6], [35, 34]] }, { p: [[60, 6], [60, 34]] }, { p: [[90, 6], [90, 34]] }, { p: [[120, 6], [120, 34]] }], zones: [{ id: 'f', r: [84, 4, 22, 32], col: 'yellow', label: 'FORN|HORNO' }] },
            prog: 'start{ set:n,0 while:$n<3{ until:M=1{ run:all,fwd,120 } change:n,1 num:$n until:M=0{ run:all,fwd,120 } } stop:all }', vars: ['n'], varNames: { n: 'comptador|contador' } },
          x: "Avança <b>fins que</b> el sensor del mig veu negre, suma 1, mostra el número i avança <b>fins que</b> torna a veure blanc: així compta cada línia <b>una sola vegada</b>. Amb 3, surt del «mentre» i para al forn.|Avanza <b>hasta que</b> el sensor del medio ve negro, suma 1, muestra el número y avanza <b>hasta que</b> vuelve a ver blanco: así cuenta cada línea <b>una sola vez</b>. Con 3, sale del «mientras» y para en el horno." }
      ] },
      { k: 'quiz', ph: 'mans', q: "La variable <b>velocitat</b> val 50. El programa fa <b>canvia velocitat en 30</b> i després, una altra vegada, <b>canvia velocitat en 30</b>. Quant val ara?|La variable <b>velocidad</b> vale 50. El programa hace <b>cambia velocidad en 30</b> y después, otra vez, <b>cambia velocidad en 30</b>. ¿Cuánto vale ahora?",
        opts: ['110|110', '30|30', '80|80'], a: 0,
        ex: "50 + 30 = 80, i 80 + 30 = 110. Si hagués fet «posa velocitat a 30», valdria 30.|50 + 30 = 80, y 80 + 30 = 110. Si hubiera hecho «pon velocidad a 30», valdría 30." },
      { k: 'seq', ph: 'mans', q: "Ordena el programa que <b>compta 3 línies negres</b> i para.|Ordena el programa que <b>cuenta 3 líneas negras</b> y para.",
        items: ["Posa comptador a 0|Pon contador a 0", "Mentre comptador < 3:|Mientras contador < 3:", "… avança fins que el sensor M vegi negre|… avanza hasta que el sensor M vea negro", "… canvia comptador en 1|… cambia contador en 1", "… avança fins que el sensor M torni a veure blanc|… avanza hasta que el sensor M vuelva a ver blanco", "Atura els motors|Para los motores"],
        ex: "Primer el comptador a 0. Dins del bucle, se suma 1 a la línia i s'espera a sortir-ne abans de buscar-ne una altra.|Primero el contador a 0. Dentro del bucle, se suma 1 en la línea y se espera a salir de ella antes de buscar otra." },
      { k: 'rpredict', ph: 'prova', q: "La velocitat comença a 60 i, cada segon, puja 60 (60, 120, 180). <b>On s'aturarà el robot?</b>|La velocidad empieza en 60 y, cada segundo, sube 60 (60, 120, 180). <b>¿Dónde se parará el robot?</b>",
        w: { w: 130, h: 40, bot: [12, 20, 90], marks: { A: [24, 20], B: [47, 20], C: [82, 20] } }, prog: 'start{ set:vel,60 rep:3{ run:all,fwd,$vel wait:1000 change:vel,60 } stop:all }', scripts: ['start'], vars: ['vel'], varNames: { vel: 'velocitat|velocidad' }, a: 'B',
        ex: "A 60 fa ~4 cm en un segon, a 120 ~12 cm i a 180 ~19 cm: uns 35 cm en total, fins a la B. La A seria si la velocitat no canviés mai.|A 60 hace ~4 cm en un segundo, a 120 ~12 cm y a 180 ~19 cm: unos 35 cm en total, hasta la B. La A sería si la velocidad no cambiara nunca." },
      { k: 'rspot', ph: 'investiga', q: "Aquest robot havia de parar a la tercera línia, però no para mai! El comptador es queda a 1. Pots executar-lo. <b>Toca el bloc que falla.</b>|Este robot tenía que parar en la tercera línea, ¡pero no para nunca! El contador se queda en 1. Puedes ejecutarlo. <b>Toca el bloque que falla.</b>",
        w: { w: 150, h: 40, bot: [12, 20, 90], lines: [{ p: [[35, 6], [35, 34]] }, { p: [[60, 6], [60, 34]] }, { p: [[90, 6], [90, 34]] }], walls: [[140, 4, 6, 32]], time: 12 },
        prog: 'start{ set:n,0 while:$n<3{ until:M=1{ run:all,fwd,120 } set:n,1! until:M=0{ run:all,fwd,120 } } stop:all }', scripts: ['start'], vars: ['n'], varNames: { n: 'comptador|contador' },
        yes: "Exacte! «Posa comptador a 1» el deixa sempre a 1. Calia «canvia comptador en 1», que suma.|¡Exacto! «Pon contador a 1» lo deja siempre en 1. Hacía falta «cambia contador en 1», que suma.",
        ex: "És el «posa comptador a 1»: cada línia hi torna a posar un 1, i 1 mai no arriba a 3. Calia «canvia comptador en 1».|Es el «pon contador a 1»: cada línea vuelve a poner un 1, y 1 nunca llega a 3. Hacía falta «cambia contador en 1»." },
      { k: 'quiz', ph: 'investiga', q: "Un comptador ha comptat <b>561</b> en un carrer amb 3 línies! El programa fa: «mentre distància > 12: endavant; si M = 1, canvia comptador en 1». Què passa?|¡Un contador ha contado <b>561</b> en una calle con 3 líneas! El programa hace: «mientras distancia > 12: adelante; si M = 1, cambia contador en 1». ¿Qué pasa?",
        opts: ["Mentre el sensor és damunt de la mateixa línia, el bucle hi passa moltes vegades i suma cada vegada|Mientras el sensor está encima de la misma línea, el bucle pasa muchas veces y suma cada vez", "El sensor de línia està espatllat|El sensor de línea está estropeado", "La variable no pot comptar més de 3|La variable no puede contar más de 3"], a: 0,
        ex: "El bucle dona moltes voltes cada segon. Per comptar cada línia una vegada, després de sumar cal esperar <b>fins que</b> el sensor torni a veure blanc.|El bucle da muchas vueltas cada segundo. Para contar cada línea una vez, después de sumar hay que esperar <b>hasta que</b> el sensor vuelva a ver blanco." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Fes de robot que accelera! A pas de formiga i, a cada palmada, passes una mica més llargues. Ara compta en veu alta les rajoles que trepitges: ets el comptador!|¡Haz de robot que acelera! A paso de hormiga y, a cada palmada, pasos un poco más largos. Ahora cuenta en voz alta las baldosas que pisas: ¡eres el contador!" },
      { k: 'robo', ph: 'repte', q: "Els <b>ous</b> no poden fer sotracs. El programa repeteix 6 vegades «motors a velocitat», però la velocitat no canvia i el robot no arriba. Afegeix el bloc que la fa <b>pujar 30 a cada volta</b> (40, 70, 100…) fins a la zona dels OUS.|Los <b>huevos</b> no pueden dar botes. El programa repite 6 veces «motores a velocidad», pero la velocidad no cambia y el robot no llega. Añade el bloque que la hace <b>subir 30 en cada vuelta</b> (40, 70, 100…) hasta la zona de los HUEVOS.",
        w: { w: 130, h: 50, bot: [12, 25, 90], zones: [{ id: 'z', r: [34, 10, 24, 30], col: 'green', label: 'OUS|HUEVOS' }], time: 12,
          goal: [{ k: 'zone', id: 'z', stop: true }, { k: 'var', v: 'vel', eq: 220 }, { k: 'nohit' }] },
        pal: ['run', 'stop', 'wait', 'set', 'change', 'rep'], ops: [], scripts: ['start'], vars: ['vel'], varNames: { vel: 'velocitat|velocidad' },
        prog: 'start{ set:vel,40 rep:6{ run:all,fwd,$vel wait:500 } stop:all }', sol: 'start{ set:vel,40 rep:6{ run:all,fwd,$vel wait:500 change:vel,30 } stop:all }',
        hint: "Posa un bloc «canvia velocitat en 30» dins del «repeteix», després de l'espera.|Pon un bloque «cambia velocidad en 30» dentro del «repite», después de la espera." },
      { k: 'robo', ph: 'repte', q: "Ruta de repartiment: el robot para al BAR, al FORN i a l'ESCOLA. Tots els motors fan servir la variable <b>velocitat</b>, però a 100 no arriba a temps. <b>Canvia només un número</b> perquè pari a les tres parades. (Pista: a 150 fa uns 15 cm cada segon i les parades són a uns 30 cm l'una de l'altra.)|Ruta de reparto: el robot para en el BAR, en el HORNO y en la ESCUELA. Todos los motores usan la variable <b>velocidad</b>, pero a 100 no llega a tiempo. <b>Cambia solo un número</b> para que pare en las tres paradas. (Pista: a 150 hace unos 15 cm cada segundo y las paradas están a unos 30 cm una de otra.)",
        w: { w: 140, h: 50, bot: [12, 25, 90], zones: [{ id: 'a', r: [33, 8, 20, 34], col: 'orange', label: 'BAR|BAR' }, { id: 'b', r: [64, 8, 20, 34], col: 'yellow', label: 'FORN|HORNO' }, { id: 'c', r: [95, 8, 22, 34], col: 'green', label: 'ESCOLA|ESCUELA' }], time: 14,
          goal: [{ k: 'at', t: 2.6, moving: false, zone: 'a', why: "Al segon 2,6, el robot ha d'estar aturat al BAR.|En el segundo 2,6, el robot tiene que estar parado en el BAR." }, { k: 'at', t: 5.4, moving: false, zone: 'b', why: "Al segon 5,4, el robot ha d'estar aturat al FORN.|En el segundo 5,4, el robot tiene que estar parado en el HORNO." }, { k: 'zone', id: 'c', stop: true }, { k: 'nohit' }] },
        pal: ['run', 'stop', 'wait', 'set', 'change'], ops: [], scripts: ['start'], vars: ['vel'], varNames: { vel: 'velocitat|velocidad' }, max: 12,
        prog: 'start{ set:vel,100 run:all,fwd,$vel wait:2000 stop:all wait:800 run:all,fwd,$vel wait:2000 stop:all wait:800 run:all,fwd,$vel wait:2000 stop:all }',
        sol: 'start{ set:vel,150 run:all,fwd,$vel wait:2000 stop:all wait:800 run:all,fwd,$vel wait:2000 stop:all wait:800 run:all,fwd,$vel wait:2000 stop:all }',
        hint: "No cal tocar els tres motors: toca el número de «posa velocitat a…». Per fer 30 cm en 2 segons, 15 cm cada segon: velocitat 150.|No hace falta tocar los tres motores: toca el número de «pon velocidad a…». Para hacer 30 cm en 2 segundos, 15 cm cada segundo: velocidad 150." },
      { k: 'robo', ph: 'repte', q: "El forn és just després del <b>tercer pas de vianants</b>, però a cada carrer els passos són a llocs diferents (mira les 3 pistes). Fes que el robot <b>compti les línies</b> i pari després de la tercera.|El horno está justo después del <b>tercer paso de cebra</b>, pero en cada calle los pasos están en sitios diferentes (mira las 3 pistas). Haz que el robot <b>cuente las líneas</b> y pare después de la tercera.",
        w: { w: 150, h: 40, bot: [12, 20, 90], lines: [{ p: [[35, 6], [35, 34]] }, { p: [[60, 6], [60, 34]] }, { p: [[90, 6], [90, 34]] }, { p: [[120, 6], [120, 34]] }], zones: [{ id: 'f', r: [84, 4, 22, 32], col: 'yellow', label: 'FORN|HORNO' }], time: 20,
          goal: [{ k: 'zone', id: 'f', stop: true }, { k: 'var', v: 'n', eq: 3 }, { k: 'nohit' }],
          alts: [{ lines: [{ p: [[30, 6], [30, 34]] }, { p: [[48, 6], [48, 34]] }, { p: [[70, 6], [70, 34]] }, { p: [[110, 6], [110, 34]] }], zones: [{ id: 'f', r: [64, 4, 22, 32], col: 'yellow', label: 'FORN|HORNO' }] },
            { lines: [{ p: [[45, 6], [45, 34]] }, { p: [[80, 6], [80, 34]] }, { p: [[118, 6], [118, 34]] }], zones: [{ id: 'f', r: [112, 4, 22, 32], col: 'yellow', label: 'FORN|HORNO' }] }] },
        pal: ['run', 'stop', 'set', 'change', 'while', 'until', 'num'], ops: ['M'], scripts: ['start'], vars: ['n'], varNames: { n: 'comptador|contador' },
        prog: 'start{ set:n,0 }', sol: 'start{ set:n,0 while:$n<3{ until:M=1{ run:all,fwd,120 } change:n,1 until:M=0{ run:all,fwd,120 } } stop:all }',
        hint: "«Mentre comptador < 3»: a dins, «repeteix fins que M = 1» amb el motor, «canvia comptador en 1» i «repeteix fins que M = 0» amb el motor. Fora del bucle, atura't.|«Mientras contador < 3»: dentro, «repite hasta que M = 1» con el motor, «cambia contador en 1» y «repite hasta que M = 0» con el motor. Fuera del bucle, párate." },
      { k: 'robo', ph: 'repte', extra: true, q: "<b>⭐ Repte extra: inspecció del carrer.</b> El robot va fins a la paret del final (sense tocar-la), <b>comptant totes les línies</b> que trepitja, i després <b>mostra el número</b>. Cada pista té un nombre de línies diferent!|<b>⭐ Reto extra: inspección de la calle.</b> El robot va hasta la pared del final (sin tocarla), <b>contando todas las líneas</b> que pisa, y después <b>muestra el número</b>. ¡Cada pista tiene un número de líneas diferente!",
        w: { w: 150, h: 40, bot: [12, 20, 90], walls: [[138, 4, 6, 32]], lines: [{ p: [[35, 6], [35, 34]] }, { p: [[62, 6], [62, 34]] }, { p: [[95, 6], [95, 34]] }], time: 20,
          goal: [{ k: 'var', v: 'n', eq: 3 }, { k: 'near', min: 5, max: 20 }, { k: 'nohit' }],
          alts: [{ lines: [{ p: [[30, 6], [30, 34]] }, { p: [[52, 6], [52, 34]] }, { p: [[80, 6], [80, 34]] }, { p: [[104, 6], [104, 34]] }, { p: [[118, 6], [118, 34]] }], goal: [{ k: 'var', v: 'n', eq: 5 }, { k: 'near', min: 5, max: 20 }, { k: 'nohit' }] },
            { lines: [{ p: [[50, 6], [50, 34]] }, { p: [[100, 6], [100, 34]] }], goal: [{ k: 'var', v: 'n', eq: 2 }, { k: 'near', min: 5, max: 20 }, { k: 'nohit' }] }] },
        pal: ['run', 'stop', 'set', 'change', 'while', 'until', 'if', 'num'], ops: ['dist', 'M'], scripts: ['start'], vars: ['n'], varNames: { n: 'comptador|contador' },
        sol: 'start{ set:n,0 while:dist>12{ run:all,fwd,120 if:M=1{ change:n,1 until:M=0{ run:all,fwd,120 } } } stop:all num:$n }',
        hint: "«Mentre distància > 12»: endavant i, si M = 1, suma 1 i espera «fins que M = 0» (si no, comptaràs centenars!). Al final, atura't i mostra el comptador.|«Mientras distancia > 12»: adelante y, si M = 1, suma 1 y espera «hasta que M = 0» (¡si no, contarás cientos!). Al final, párate y muestra el contador." },
      { k: 'rcreate', ph: 'crea', name: "El repartidor d'ous|El repartidor de huevos",
        q: "El teu repartidor d'ous! Ha de sortir <b>a poc a poc</b> i anar <b>accelerant</b> amb una variable de velocitat, <b>comptar els 4 passos de vianants</b> i aturar-se al FORN, just després del quart. Al final, que mostri el comptador.|¡Tu repartidor de huevos! Tiene que salir <b>despacio</b> e ir <b>acelerando</b> con una variable de velocidad, <b>contar los 4 pasos de cebra</b> y pararse en el HORNO, justo después del cuarto. Al final, que muestre el contador.",
        crit: ["Fa servir la variable velocitat als motors i la fa canviar|Usa la variable velocidad en los motores y la hace cambiar", "Compta els 4 passos amb el comptador|Cuenta los 4 pasos con el contador", "S'atura al FORN sense xocar|Se para en el HORNO sin chocar"],
        w: { w: 150, h: 40, bot: [12, 20, 90], lines: [{ p: [[30, 6], [30, 34]] }, { p: [[50, 6], [50, 34]] }, { p: [[75, 6], [75, 34]] }, { p: [[105, 6], [105, 34]] }], zones: [{ id: 'f', r: [100, 4, 26, 32], col: 'yellow', label: 'FORN|HORNO' }], time: 20,
          goal: [{ k: 'zone', id: 'f', stop: true }, { k: 'var', v: 'n', eq: 4 }, { k: 'nohit' }] },
        pal: ['run', 'stop', 'wait', 'set', 'change', 'rep', 'while', 'until', 'if', 'else', 'num', 'icon', 'car', 'under', 'note'], ops: ['dist', 'M'], scripts: ['start'], vars: ['vel', 'n'], varNames: { vel: 'velocitat|velocidad', n: 'comptador|contador' },
        check: P => { const k = [], w = l => (l || []).forEach(b => { k.push(b); if (Array.isArray(b.b)) w(b.b); w(b.e); }); w(P.start); const usesVel = k.some(b => b.k === 'run' && b.s && b.s.r === 'var' && b.s.v === 'vel'), chVel = k.some(b => b.k === 'change' && b.v === 'vel'); return usesVel && chVel ? null : "Funciona, però falta la velocitat que canvia: posa la variable velocitat als motors i fes-la créixer amb «canvia velocitat en…».|Funciona, pero falta la velocidad que cambia: pon la variable velocidad en los motores y hazla crecer con «cambia velocidad en…»."; },
        sol: 'start{ set:n,0 set:vel,60 while:$n<4{ until:M=1{ run:all,fwd,$vel } change:n,1 change:vel,30 until:M=0{ run:all,fwd,$vel } } stop:all num:$n }' },
      { k: 'quiz', ph: 'tanca', q: "El repartidor fa «posa velocitat a 40» i, a cada volta, «canvia velocitat en 30». Encara accelera massa de pressa i els ous trontollen. <b>Què canvies?</b>|El repartidor hace «pon velocidad a 40» y, en cada vuelta, «cambia velocidad en 30». Todavía acelera demasiado deprisa y los huevos se tambalean. <b>¿Qué cambias?</b>",
        opts: ["El 30 per un número més petit, com 10|El 30 por un número más pequeño, como 10", "El 40 per 255|El 40 por 255", "Canvio el «canvia velocitat en 30» per «posa velocitat a 30»|Cambio el «cambia velocidad en 30» por «pon velocidad a 30»"], a: 0,
        ex: "«Canvia en» decideix quant puja la velocitat a cada volta: si suma menys, l'arrencada és més suau.|«Cambia en» decide cuánto sube la velocidad en cada vuelta: si suma menos, el arranque es más suave." },
      { k: 'quiz', ph: 'tanca', q: "El comptador val 5. Quin bloc el deixa a 6?|El contador vale 5. ¿Qué bloque lo deja en 6?",
        opts: ["Canvia comptador en 1|Cambia contador en 1", "Posa comptador a 1|Pon contador a 1", "Mostra el número comptador|Muestra el número contador"], a: 0,
        ex: "«Canvia en 1» suma: 5 + 1 = 6. «Posa a 1» el deixaria a 1, i «mostra» només l'ensenya.|«Cambia en 1» suma: 5 + 1 = 6. «Pon a 1» lo dejaría en 1, y «muestra» solo lo enseña." },
      { k: 'feel', ph: 'tanca' }
    ] },

  /* ---------- Sessió 2 · Com més lluny, més de pressa (calcula i control proporcional) ---------- */
  { id: 'k6-2', t: 'Com més lluny, més de pressa|Cuanto más lejos, más deprisa', min: 45, badge: 'k_prop',
    learn: ["El bloc «posa … a … × …» calcula un número nou amb un sensor o una variable, i dins de «per sempre» el torna a calcular a cada volta.|El bloque «pon … a … × …» calcula un número nuevo con un sensor o una variable, y dentro de «para siempre» lo vuelve a calcular en cada vuelta.",
      "Control proporcional: velocitat = error × k (error = distància − distància que vull; k és el multiplicador). Com més lluny, més de pressa; com més a prop, més suau.|Control proporcional: velocidad = error × k (error = distancia − distancia que quiero; k es el multiplicador). Cuanto más lejos, más deprisa; cuanto más cerca, más suave.",
      "Si k és petit, el robot frena massa aviat i per sota de velocitat 30 s'atura lluny (zona morta); amb un k més gran, arriba més ràpid i més a prop.|Si k es pequeño, el robot frena demasiado pronto y por debajo de velocidad 30 se para lejos (zona muerta); con un k más grande, llega más rápido y más cerca."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "A la unitat 3 vas fer parar el robot davant d'un mur amb «si distància < 15, atura't; si no, endavant». Com frena aquest robot?|En la unidad 3 hiciste parar el robot delante de un muro con «si distancia < 15, párate; si no, adelante». ¿Cómo frena este robot?",
        opts: ["De cop: va a la mateixa velocitat fins al final i para en sec|De golpe: va a la misma velocidad hasta el final y para en seco", "A poc a poc, com més a prop més lent|Poco a poco, cuanto más cerca más lento", "No frena mai|No frena nunca"], a: 0,
        ex: "És un control de <b>tot o res</b>: o endavant, o aturat. Avui farem un robot que frena <b>suau</b>.|Es un control de <b>todo o nada</b>: o adelante, o parado. Hoy haremos un robot que frena <b>suave</b>." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'taller', title: "L'estació de càrrega|La estación de carga",
        t: "El robot repartidor s'ha d'acostar a l'<b>estació de càrrega</b> fins a uns 10 cm: si hi arriba de cop, <b>xoca</b>; si para lluny, <b>no es carrega</b>. Com quan aparques una bici: lluny, de pressa; a prop, <b>a poc a poc</b>. És el <b>control proporcional</b>.|El robot repartidor se tiene que acercar a la <b>estación de carga</b> hasta unos 10 cm: si llega de golpe, <b>choca</b>; si para lejos, <b>no se carga</b>. Como cuando aparcas una bici: lejos, deprisa; cerca, <b>despacio</b>. Es el <b>control proporcional</b>." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'La idea|La idea', t: 'Com més lluny, més de pressa|Cuanto más lejos, más deprisa', anim: 'k6prop',
          x: "En lloc de «velocitat 150» o «atura't», la velocitat <b>depèn de la distància</b>: lluny → alta; a prop → baixa; just on volem → 0. És <span class='hl'>proporcional</span>: si la distància es fa la meitat, la velocitat també.|En lugar de «velocidad 150» o «párate», la velocidad <b>depende de la distancia</b>: lejos → alta; cerca → baja; justo donde queremos → 0. Es <span class='hl'>proporcional</span>: si la distancia se hace la mitad, la velocidad también.",
          tip: "Molts cotxes moderns frenen sols així quan s'acosten al cotxe del davant.|Muchos coches modernos frenan solos así cuando se acercan al coche de delante." },
        { k: 'El bloc «calcula»|El bloque «calcula»', t: 'velocitat = distància × 3|velocidad = distancia × 3',
          robo: { w: { w: 130, h: 40, bot: [12, 20, 90], walls: [[112, 4, 6, 32]] }, prog: 'forever{ calc:v,dist,*,3 run:all,fwd,$v }', varNames: { v: 'velocitat|velocidad' } },
          x: "<b>Posa velocitat a distància × 3</b> multiplica el que mesura l'ultrasò. <b>80 cm → 240 · 50 cm → 150 · 30 cm → 90 · 10 cm → 30</b> (i el motor ja no té força). Dins de «per sempre», es <b>torna a calcular a cada volta</b> i el robot frena sol.|<b>Pon velocidad a distancia × 3</b> multiplica lo que mide el ultrasonido. <b>80 cm → 240 · 50 cm → 150 · 30 cm → 90 · 10 cm → 30</b> (y el motor ya no tiene fuerza). Dentro de «para siempre», se <b>vuelve a calcular en cada vuelta</b> y el robot frena solo.",
          tip: "El bloc pot sumar, restar, multiplicar i dividir. Si el resultat passa de 255, el motor va a 255.|El bloque puede sumar, restar, multiplicar y dividir. Si el resultado pasa de 255, el motor va a 255." },
        { k: "L'error|El error", t: 'Quant em falta?|¿Cuánto me falta?',
          robo: { w: { w: 130, h: 40, bot: [12, 20, 90], walls: [[112, 4, 6, 32]] }, prog: 'forever{ calc:e,dist,-,10 calc:v,$e,*,10 run:all,fwd,$v }', varNames: { e: 'error|error', v: 'velocitat|velocidad' } },
          x: "Volem parar a <b>10 cm</b>. L'<span class='hl'>error</span> és el que falta: <b>error = distància − 10</b> (a 50 cm, 40; a 10 cm, 0). Després, <b>velocitat = error × k</b>: el <b>multiplicador k</b> diu com de «valent» és el robot. Aquí k = 10.|Queremos parar a <b>10 cm</b>. El <span class='hl'>error</span> es lo que falta: <b>error = distancia − 10</b> (a 50 cm, 40; a 10 cm, 0). Después, <b>velocidad = error × k</b>: el <b>multiplicador k</b> dice lo «valiente» que es el robot. Aquí k = 10.",
          tip: "Al robot de veritat, la velocitat ha d'anar de 0 a 255: el programa que s'obre a MakeCode ja la limita.|En el robot de verdad, la velocidad tiene que ir de 0 a 255: el programa que se abre en MakeCode ya la limita." },
        { k: "El multiplicador k|El multiplicador k", t: 'k petit o k gran?|¿k pequeño o k grande?', anim: 'k6gain',
          x: "Amb <b>k petit</b> (×2, ×3), comença a frenar molt lluny i arriba molt a poc a poc. Amb <b>k gran</b> (×10, ×20), va de pressa gairebé fins al final i frena al darrer moment. Amb un k exagerat, torna a ser com el «tot o res».|Con <b>k pequeño</b> (×2, ×3), empieza a frenar muy lejos y llega muy despacio. Con <b>k grande</b> (×10, ×20), va deprisa casi hasta el final y frena en el último momento. Con un k exagerado, vuelve a ser como el «todo o nada»." },
        { k: 'Compte!|¡Cuidado!', t: 'La zona morta no perdona|La zona muerta no perdona', anim: 'k6dead',
          x: "Amb <b>error × 2</b>, quan falten 15 cm la velocitat ja és 30… i el motor <b>no es mou</b>! S'atura a uns 25 cm. Amb error × 10, arriba a uns 13 cm.|Con <b>error × 2</b>, cuando faltan 15 cm la velocidad ya es 30… ¡y el motor <b>no se mueve</b>! Se para a unos 25 cm. Con error × 10, llega a unos 13 cm.",
          bad: "Calculant la velocitat, sempre para just on vull.|Calculando la velocidad, siempre para justo donde quiero.", good: "Para quan la velocitat baixa de ~30: amb k petit, massa lluny.|Para cuando la velocidad baja de ~30: con k pequeño, demasiado lejos." }
      ] },
      { k: 'quiz', ph: 'mans', q: "El programa fa <b>error = distància − 10</b> i <b>velocitat = error × 5</b>. L'ultrasò mesura <b>40 cm</b>. A quina velocitat va el motor?|El programa hace <b>error = distancia − 10</b> y <b>velocidad = error × 5</b>. El ultrasonido mide <b>40 cm</b>. ¿A qué velocidad va el motor?",
        opts: ['150|150', '200|200', '45|45'], a: 0,
        ex: "40 − 10 = 30 d'error, i 30 × 5 = 150.|40 − 10 = 30 de error, y 30 × 5 = 150." },
      { k: 'seq', ph: 'mans', q: "El robot repeteix aquests passos moltes vegades cada segon: és el <b>bucle de control</b>. Posa'ls en ordre.|El robot repite estos pasos muchas veces cada segundo: es el <b>bucle de control</b>. Ponlos en orden.",
        items: ["Mesura la distància amb l'ultrasò|Mide la distancia con el ultrasonido", "Calcula l'error: distància − 10|Calcula el error: distancia − 10", "Calcula la velocitat: error × k|Calcula la velocidad: error × k", "Engega els motors a aquesta velocitat|Enciende los motores a esa velocidad", "Torna a començar (per sempre)|Vuelve a empezar (para siempre)"],
        ex: "Sentir → pensar → actuar, i tornar a començar: el robot corregeix la velocitat a cada volta.|Sentir → pensar → actuar, y volver a empezar: el robot corrige la velocidad en cada vuelta." },
      { k: 'rpredict', ph: 'prova', q: "Velocitat = distància × 2. El robot frena a mesura que s'acosta al mur. <b>On es quedarà aturat?</b> (Recorda la zona morta.)|Velocidad = distancia × 2. El robot frena a medida que se acerca al muro. <b>¿Dónde se quedará parado?</b> (Recuerda la zona muerta.)",
        w: { w: 130, h: 40, bot: [12, 20, 90], walls: [[110, 4, 6, 32]], marks: { A: [100, 20], B: [89, 20], C: [70, 20] }, time: 18 }, prog: 'forever{ calc:v,dist,*,2 run:all,fwd,$v }', scripts: ['forever'], vars: ['v'], varNames: { v: 'velocitat|velocidad' }, a: 'B',
        ex: "Quan la distància és 15 cm, la velocitat és 15 × 2 = 30 i el motor ja no té força: s'atura a uns 15-16 cm del mur, a la B.|Cuando la distancia es 15 cm, la velocidad es 15 × 2 = 30 y el motor ya no tiene fuerza: se para a unos 15-16 cm del muro, en la B." },
      { k: 'rspot', ph: 'investiga', q: "Aquest robot havia de parar a 10 cm del carregador, però es queda a uns 25 cm i no es carrega. Pots executar-lo. <b>Toca el bloc que cal canviar.</b>|Este robot tenía que parar a 10 cm del cargador, pero se queda a unos 25 cm y no se carga. Puedes ejecutarlo. <b>Toca el bloque que hay que cambiar.</b>",
        w: { w: 130, h: 40, bot: [12, 20, 90], walls: [[112, 4, 6, 32]], zones: [{ id: 'c', r: [92, 6, 20, 28], col: 'blue', label: 'CÀRREGA|CARGA' }], time: 14 },
        prog: 'forever{ calc:e,dist,-,10 calc:v,$e,*,2! run:all,fwd,$v }', scripts: ['forever'], vars: ['e', 'v'], varNames: { e: 'error|error', v: 'velocitat|velocidad' },
        yes: "Exacte! El multiplicador k = 2 és massa petit: quan falten 15 cm, la velocitat ja és 30 i el motor s'atura. Prova k = 10.|¡Exacto! El multiplicador k = 2 es demasiado pequeño: cuando faltan 15 cm, la velocidad ya es 30 y el motor se para. Prueba k = 10.",
        ex: "És el «× 2»: amb un multiplicador tan petit, la velocitat baixa de 30 quan falten 15 cm i el robot es queda lluny.|Es el «× 2»: con un multiplicador tan pequeño, la velocidad baja de 30 cuando faltan 15 cm y el robot se queda lejos." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Sigues un robot proporcional! Camina cap a una paret: com més a prop, <b>passes més petites</b>, fins a un pam. Ara amb k gran: passes llargues fins al final i frenada ràpida (amb compte!).|¡Sé un robot proporcional! Camina hacia una pared: cuanto más cerca, <b>pasos más pequeños</b>, hasta un palmo. Ahora con k grande: pasos largos hasta el final y frenada rápida (¡con cuidado!)." },
      { k: 'robo', ph: 'repte', q: "El robot va a velocitat 150 i xoca contra el mur. Fes que <b>la velocitat sigui la distància × 3</b> perquè freni sol i s'aturi abans del mur, a les 3 pistes. (Aquí no hi ha bloc «si»: la velocitat s'ha de calcular!)|El robot va a velocidad 150 y choca contra el muro. Haz que <b>la velocidad sea la distancia × 3</b> para que frene solo y se pare antes del muro, en las 3 pistas. (Aquí no hay bloque «si»: ¡la velocidad se tiene que calcular!)",
        w: { w: 140, h: 50, bot: [15, 25, 90], walls: [[120, 5, 6, 40]], time: 20, goal: [{ k: 'near', min: 6, max: 22 }, { k: 'nohit' }], alts: [{ walls: [[75, 5, 6, 40]] }, { walls: [[45, 5, 6, 40]] }] },
        pal: ['run', 'calc'], ops: ['dist'], scripts: ['forever'], vars: ['v'], varNames: { v: 'velocitat|velocidad' },
        prog: 'forever{ run:all,fwd,150 }', sol: 'forever{ calc:v,dist,*,3 run:all,fwd,$v }',
        hint: "Posa «posa velocitat a distància × 3» abans del motor, i al motor tria la variable velocitat en lloc de 150.|Pon «pon velocidad a distancia × 3» antes del motor, y en el motor elige la variable velocidad en lugar de 150." },
      { k: 'robo', ph: 'repte', q: "Ara cal parar <b>a uns 10 cm</b> del carregador (entre 6 i 15 cm). El programa ja calcula l'error i la velocitat, però amb <b>k = 3</b> es queda massa lluny. Troba un multiplicador k que funcioni a les 3 pistes.|Ahora hay que parar <b>a unos 10 cm</b> del cargador (entre 6 y 15 cm). El programa ya calcula el error y la velocidad, pero con <b>k = 3</b> se queda demasiado lejos. Encuentra un multiplicador k que funcione en las 3 pistas.",
        w: { w: 140, h: 50, bot: [15, 25, 90], walls: [[120, 5, 6, 40]], zones: [{ id: 'c', r: [100, 9, 20, 32], col: 'blue', label: 'CÀRREGA|CARGA' }], time: 20, goal: [{ k: 'near', min: 6, max: 15 }, { k: 'nohit' }],
          alts: [{ walls: [[80, 5, 6, 40]], zones: [{ id: 'c', r: [60, 9, 20, 32], col: 'blue', label: 'CÀRREGA|CARGA' }] }, { walls: [[50, 5, 6, 40]], zones: [{ id: 'c', r: [30, 9, 20, 32], col: 'blue', label: 'CÀRREGA|CARGA' }] }] },
        pal: ['run', 'calc'], ops: ['dist'], scripts: ['forever'], vars: ['e', 'v'], varNames: { e: 'error|error', v: 'velocitat|velocidad' },
        prog: 'forever{ calc:e,dist,-,10 calc:v,$e,*,3 run:all,fwd,$v }', sol: 'forever{ calc:e,dist,-,10 calc:v,$e,*,10 run:all,fwd,$v }',
        hint: "Toca el «3» del segon bloc de calcular i prova números més grans: 5, 10, 15… Mira a quina distància s'atura.|Toca el «3» del segundo bloque de calcular y prueba números más grandes: 5, 10, 15… Mira a qué distancia se para." },
      { k: 'robo', ph: 'repte', q: "Urgent: el robot té poca bateria i ha d'arribar al carregador <b>abans del segon 5</b>, aturat i sense xocar. La pista 1 és molt llarga! Calcula l'error (distància − 10) i la velocitat (error × k) i tria un k prou valent.|Urgente: el robot tiene poca batería y tiene que llegar al cargador <b>antes del segundo 5</b>, parado y sin chocar. ¡La pista 1 es muy larga! Calcula el error (distancia − 10) y la velocidad (error × k) y elige un k suficientemente valiente.",
        w: { w: 170, h: 50, bot: [15, 25, 90], walls: [[150, 5, 6, 40]], zones: [{ id: 'c', r: [126, 8, 24, 34], col: 'blue', label: 'CÀRREGA|CARGA' }], time: 8,
          goal: [{ k: 'at', t: 5, moving: false, zone: 'c', why: "Al segon 5, el robot ha d'estar aturat al carregador. Prova un k més gran.|En el segundo 5, el robot tiene que estar parado en el cargador. Prueba un k más grande." }, { k: 'near', min: 6, max: 15 }, { k: 'nohit' }],
          alts: [{ walls: [[120, 5, 6, 40]], zones: [{ id: 'c', r: [96, 8, 24, 34], col: 'blue', label: 'CÀRREGA|CARGA' }] }] },
        pal: ['run', 'calc'], ops: ['dist'], scripts: ['forever'], vars: ['e', 'v'], varNames: { e: 'error|error', v: 'velocitat|velocidad' },
        sol: 'forever{ calc:e,dist,-,10 calc:v,$e,*,30 run:all,fwd,$v }',
        hint: "Amb k = 10 arriba massa tard a la pista 1. Prova k = 25 o 30: anirà a tota velocitat fins a prop i frenarà al final.|Con k = 10 llega demasiado tarde en la pista 1. Prueba k = 25 o 30: irá a toda velocidad hasta cerca y frenará al final." },
      { k: 'robo', ph: 'repte', extra: true, q: "<b>⭐ Repte extra: endavant i enrere.</b> A vegades el robot comença <b>massa a prop</b> del carregador (pista 1). Ha d'acabar a uns 15 cm (entre 10 i 20). Si l'error és negatiu, <b>recula</b> amb velocitat error × −12; si no, endavant amb error × 12.|<b>⭐ Reto extra: adelante y atrás.</b> A veces el robot empieza <b>demasiado cerca</b> del cargador (pista 1). Tiene que acabar a unos 15 cm (entre 10 y 20). Si el error es negativo, <b>retrocede</b> con velocidad error × −12; si no, adelante con error × 12.",
        w: { w: 140, h: 50, bot: [15, 25, 90], walls: [[30, 5, 6, 40]], time: 15, goal: [{ k: 'near', min: 10, max: 20 }, { k: 'nohit' }], alts: [{ walls: [[110, 5, 6, 40]] }, { walls: [[45, 5, 6, 40]] }] },
        pal: ['run', 'calc', 'if', 'else'], ops: ['dist'], scripts: ['forever'], vars: ['e', 'v'], varNames: { e: 'error|error', v: 'velocitat|velocidad' },
        sol: 'forever{ calc:e,dist,-,15 if:$e<0{ calc:v,$e,*,-12 run:all,back,$v } else{ calc:v,$e,*,12 run:all,fwd,$v } }',
        hint: "error = distància − 15. «Si error < 0»: velocitat = error × −12 (un número negatiu per un altre negatiu dona positiu) i motors enrere. «Si no»: velocitat = error × 12 i motors endavant.|error = distancia − 15. «Si error < 0»: velocidad = error × −12 (un número negativo por otro negativo da positivo) y motores atrás. «Si no»: velocidad = error × 12 y motores adelante." },
      { k: 'rcreate', ph: 'crea', name: "L'estació de càrrega|La estación de carga",
        q: "La teva estació de càrrega! El robot s'acosta <b>amb control proporcional</b> fins a 6-15 cm del carregador, sense xocar, i quan gairebé no es mou encén els <b>llums del cotxe en verd</b> (s'està carregant).|¡Tu estación de carga! El robot se acerca <b>con control proporcional</b> hasta 6-15 cm del cargador, sin chocar, y cuando casi no se mueve enciende las <b>luces del coche en verde</b> (se está cargando).",
        crit: ["Calcula la velocitat amb la distància (bloc calcula)|Calcula la velocidad con la distancia (bloque calcula)", "Para a 6-15 cm sense xocar a les 2 pistes|Para a 6-15 cm sin chocar en las 2 pistas", "Al final té els llums del cotxe en verd|Al final tiene las luces del coche en verde"],
        w: { w: 140, h: 50, bot: [15, 25, 90], walls: [[120, 5, 6, 40]], zones: [{ id: 'c', r: [100, 9, 20, 32], col: 'blue', label: 'CÀRREGA|CARGA' }], time: 20, goal: [{ k: 'near', min: 6, max: 15 }, { k: 'car', c: 'green' }, { k: 'nohit' }],
          alts: [{ walls: [[70, 5, 6, 40]], zones: [{ id: 'c', r: [50, 9, 20, 32], col: 'blue', label: 'CÀRREGA|CARGA' }] }] },
        pal: ['run', 'stop', 'calc', 'set', 'change', 'if', 'else', 'car', 'under', 'icon'], ops: ['dist'], scripts: ['start', 'forever'], vars: ['e', 'v'], varNames: { e: 'error|error', v: 'velocitat|velocidad' },
        check: P => { const k = [], w = l => (l || []).forEach(b => { k.push(b); if (Array.isArray(b.b)) w(b.b); w(b.e); }); w(P.start); w(P.forever); return k.some(b => b.k === 'calc' && ((b.a && b.a.r === 'dist') || (b.y && b.y.r === 'dist'))) ? null : "Funciona, però el repte és fer-ho amb control proporcional: calcula la velocitat a partir de la distància.|Funciona, pero el reto es hacerlo con control proporcional: calcula la velocidad a partir de la distancia."; },
        sol: 'forever{ calc:e,dist,-,10 calc:v,$e,*,15 run:all,fwd,$v if:$v<40{ car:all,green } else{ car:all,yellow } }' },
      { k: 'quiz', ph: 'tanca', q: "Amb el control proporcional, què fa el robot quan és <b>lluny</b> del mur?|Con el control proporcional, ¿qué hace el robot cuando está <b>lejos</b> del muro?",
        opts: ["Va de pressa, perquè l'error és gran|Va deprisa, porque el error es grande", "Va a poc a poc, per si de cas|Va despacio, por si acaso", "S'atura|Se para"], a: 0 },
      { k: 'quiz', ph: 'tanca', q: "El teu robot s'atura massa lluny de la meta. Què hi pots canviar?|Tu robot se para demasiado lejos de la meta. ¿Qué puedes cambiar?",
        opts: ["Fer més gran el multiplicador k|Hacer más grande el multiplicador k", "Fer més petit el multiplicador k|Hacer más pequeño el multiplicador k", "Treure el «per sempre»|Quitar el «para siempre»"], a: 0,
        ex: "Amb un k més gran, la velocitat es manté per sobre de 30 fins més a prop i el robot arriba més lluny.|Con un k más grande, la velocidad se mantiene por encima de 30 hasta más cerca y el robot llega más lejos." },
      { k: 'feel', ph: 'tanca' }
    ] },

  /* ---------- Sessió 3 · Segueix el líder ---------- */
  { id: 'k6-3', t: 'Segueix el líder|Sigue al líder', min: 45, badge: 'k_lider',
    learn: ["Si el que hi ha al davant es mou, el control proporcional fa que el robot el segueixi: accelera quan s'allunya i frena quan s'acosta.|Si lo que hay delante se mueve, el control proporcional hace que el robot lo siga: acelera cuando se aleja y frena cuando se acerca.",
      "Com més de pressa va el líder, més error cal per anar igual de ràpid: el seguidor el segueix una mica més lluny.|Cuanto más deprisa va el líder, más error hace falta para ir igual de rápido: el seguidor lo sigue un poco más lejos.",
      "Amb llums, el seguidor avisa quan frena; i, si vols, amb «si error < 0, recula» també s'aparta quan el líder torna enrere.|Con luces, el seguidor avisa cuando frena; y, si quieres, con «si error < 0, retrocede» también se aparta cuando el líder vuelve atrás."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "Error = distància − 10 i velocitat = error × 5. L'ultrasò mesura <b>30 cm</b>. A quina velocitat va?|Error = distancia − 10 y velocidad = error × 5. El ultrasonido mide <b>30 cm</b>. ¿A qué velocidad va?",
        opts: ['100|100', '150|150', '20|20'], a: 0, ex: "30 − 10 = 20, i 20 × 5 = 100.|30 − 10 = 20, y 20 × 5 = 100." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'poble', title: 'El comboi del mercat|El convoy del mercado',
        t: "Dissabte hi ha mercat: farem un <b>comboi</b>! Un robot líder obre el camí i els altres el <b>segueixen</b> en fila, sense res que els uneixi. És el control proporcional d'ahir, però ara <b>el «mur» es mou</b>.|El sábado hay mercado: ¡haremos un <b>convoy</b>! Un robot líder abre el camino y los demás lo <b>siguen</b> en fila, sin nada que los una. Es el control proporcional de ayer, pero ahora <b>el «muro» se mueve</b>." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Segueix el líder|Sigue al líder', t: 'Un objectiu que es mou|Un objetivo que se mueve', anim: 'k6lead',
          x: "L'ultrasò mesura la distància fins al líder. Si el líder accelera, la distància i l'error creixen i el seguidor <b>accelera</b>. Si el líder frena, el seguidor <b>frena</b>. El programa de l'estació de càrrega serveix per seguir!|El ultrasonido mide la distancia hasta el líder. Si el líder acelera, la distancia y el error crecen y el seguidor <b>acelera</b>. Si el líder frena, el seguidor <b>frena</b>. ¡El programa de la estación de carga sirve para seguir!" },
        { k: 'Mira-ho|Míralo', t: 'El seguidor en acció|El seguidor en acción',
          robo: { w: { w: 170, h: 40, bot: [15, 20, 90], leader: { path: [[42, 20], [165, 20]], speed: 8, stopAt: 9 }, time: 13 }, prog: 'forever{ calc:e,dist,-,10 calc:v,$e,*,10 run:all,fwd,$v }', varNames: { e: 'error|error', v: 'velocitat|velocidad' } },
          x: "El líder (gris) va a 8 cm cada segon i al segon 9 s'atura, com en un semàfor. El seguidor calcula la velocitat a cada volta amb la distància i, quan el líder para, també para, a uns 13 cm.|El líder (gris) va a 8 cm cada segundo y en el segundo 9 se para, como en un semáforo. El seguidor calcula la velocidad en cada vuelta con la distancia y, cuando el líder para, también para, a unos 13 cm." },
        { k: 'Compte!|¡Cuidado!', t: 'Si el líder corre, el segueix més lluny|Si el líder corre, lo sigue más lejos',
          robo: { w: { w: 170, h: 40, bot: [15, 20, 90], leader: { path: [[42, 20], [165, 20]], speed: 14 }, time: 9 }, prog: 'forever{ calc:e,dist,-,10 calc:v,$e,*,10 run:all,fwd,$v }', varNames: { e: 'error|error', v: 'velocitat|velocidad' } },
          x: "Ara el líder va més de pressa. Per seguir-lo, el seguidor necessita més velocitat i, per tant, més error: el segueix a uns 24 cm, no a 10. Per seguir-lo més a prop, fes el k més gran.|Ahora el líder va más deprisa. Para seguirlo, el seguidor necesita más velocidad y, por tanto, más error: lo sigue a unos 24 cm, no a 10. Para seguirlo más cerca, haz el k más grande.",
          bad: "El seguidor sempre va exactament a 10 cm del líder.|El seguidor siempre va exactamente a 10 cm del líder.", good: "Quan el líder es mou, cal una mica d'error per tenir velocitat: el seguidor va una mica més lluny.|Cuando el líder se mueve, hace falta un poco de error para tener velocidad: el seguidor va un poco más lejos." },
        { k: "⭐ Saber més|⭐ Saber más", t: 'Quan el líder torna enrere|Cuando el líder vuelve atrás',
          robo: { w: { w: 160, h: 40, bot: [30, 20, 90], leader: { path: [[60, 20], [130, 20], [70, 20]], speed: 8 }, time: 18 }, prog: 'forever{ calc:e,dist,-,15 if:$e<0{ calc:v,$e,*,-15 run:all,back,$v } else{ calc:v,$e,*,15 run:all,fwd,$v } }', varNames: { e: 'error|error', v: 'velocitat|velocidad' } },
          x: "<b>Només si tens curiositat:</b> aquest líder <b>torna cap al seguidor</b>. Si l'error és negatiu (és a menys de 15 cm), el seguidor calcula velocitat = error × −15 i <b>recula</b>. Sense aquest «si», el líder hi xocaria.|<b>Solo si tienes curiosidad:</b> este líder <b>vuelve hacia el seguidor</b>. Si el error es negativo (está a menos de 15 cm), el seguidor calcula velocidad = error × −15 y <b>retrocede</b>. Sin este «si», el líder chocaría con él." }
      ] },
      { k: 'quiz', ph: 'mans', q: "El robot segueix el líder amb velocitat = (distància − 10) × 10. De sobte, el líder <b>s'atura</b>. Què fa el seguidor?|El robot sigue al líder con velocidad = (distancia − 10) × 10. De repente, el líder <b>se para</b>. ¿Qué hace el seguidor?",
        opts: ["Frena a poc a poc i s'atura una mica abans de 10 cm|Frena poco a poco y se para un poco antes de 10 cm", "Hi xoca, perquè no ho sap|Choca, porque no lo sabe", "Fa mitja volta|Da media vuelta"], a: 0,
        ex: "No li cal saber que el líder s'ha aturat: la distància, l'error i la velocitat baixen fins que el motor s'atura (a uns 13 cm).|No necesita saber que el líder se ha parado: la distancia, el error y la velocidad bajan hasta que el motor se para (a unos 13 cm)." },
      { k: 'quiz', ph: 'mans', q: "El líder va a 8 cm cada segon. El seguidor necessita velocitat <b>90</b> per anar igual. Si velocitat = error × 10, quin error tindrà quan vagi igual que el líder?|El líder va a 8 cm cada segundo. El seguidor necesita velocidad <b>90</b> para ir igual. Si velocidad = error × 10, ¿qué error tendrá cuando vaya igual que el líder?",
        opts: ["Uns 9 cm: el seguirà a uns 19 cm (10 + 9)|Unos 9 cm: lo seguirá a unos 19 cm (10 + 9)", "0 cm: el seguirà a 10 cm|0 cm: lo seguirá a 10 cm", "90 cm|90 cm"], a: 0,
        ex: "9 × 10 = 90: 9 cm d'error. Amb k = 30, només en caldrien 3 (3 × 30 = 90): un k més gran el segueix més a prop.|9 × 10 = 90: 9 cm de error. Con k = 30, solo harían falta 3 (3 × 30 = 90): un k más grande lo sigue más cerca." },
      { k: 'rpredict', ph: 'prova', q: "El líder avança i s'atura al final del seu camí. El seguidor fa velocitat = (distància − 10) × 10. <b>On es quedarà el seguidor?</b>|El líder avanza y se para al final de su camino. El seguidor hace velocidad = (distancia − 10) × 10. <b>¿Dónde se quedará el seguidor?</b>",
        w: { w: 130, h: 40, bot: [15, 20, 90], leader: { path: [[45, 20], [100, 20]], speed: 8 }, marks: { A: [90, 20], B: [78, 20], C: [55, 20] }, time: 14 }, prog: 'forever{ calc:e,dist,-,10 calc:v,$e,*,10 run:all,fwd,$v }', scripts: ['forever'], vars: ['e', 'v'], varNames: { e: 'error|error', v: 'velocitat|velocidad' }, a: 'B',
        ex: "Frena com davant d'un mur i s'atura a uns 13 cm del líder: a la B. La A seria tocar-lo!|Frena como delante de un muro y se para a unos 13 cm del líder: en la B. ¡La A sería tocarlo!" },
      { k: 'rspot', ph: 'investiga', q: "Aquest seguidor calcula bé la velocitat… però xoca amb el líder quan s'atura! Pots executar-lo. <b>Toca el bloc que falla.</b>|Este seguidor calcula bien la velocidad… ¡pero choca con el líder cuando se para! Puedes ejecutarlo. <b>Toca el bloque que falla.</b>",
        w: { w: 150, h: 40, bot: [15, 20, 90], leader: { path: [[42, 20], [110, 20]], speed: 8 }, time: 14 },
        prog: 'forever{ calc:e,dist,-,10 calc:v,$e,*,10 run:all,fwd,150! }', scripts: ['forever'], vars: ['e', 'v'], varNames: { e: 'error|error', v: 'velocitat|velocidad' },
        yes: "Exacte! El motor va sempre a 150 i no fa servir la velocitat calculada. Hi calia la variable velocitat.|¡Exacto! El motor va siempre a 150 y no usa la velocidad calculada. Hacía falta la variable velocidad.",
        ex: "És el motor: va a 150 fix, i la velocitat calculada no la fa servir ningú. Calculem-la i fem-la servir!|Es el motor: va a 150 fijo, y la velocidad calculada no la usa nadie. ¡La calculamos y la usamos!" },
      { k: 'move', ph: 'pausa', secs: 35, t: "Comboi humà! En parelles: un/a fa de líder i camina, para, accelera… L'altre/a el segueix amb el braç estirat com a «ultrasò», sense tocar-lo. Després, canvieu.|¡Convoy humano! Por parejas: uno/a hace de líder y camina, para, acelera… El otro/a lo sigue con el brazo estirado como «ultrasonido», sin tocarlo. Después, cambiad." },
      { k: 'robo', ph: 'repte', q: "El primer viatge del comboi: el nostre robot va a 150 i xoca amb el líder. Fes que <b>el segueixi</b> entre 4 i 30 cm, sense tocar-lo, amb control proporcional.|El primer viaje del convoy: nuestro robot va a 150 y choca con el líder. Haz que <b>lo siga</b> entre 4 y 30 cm, sin tocarlo, con control proporcional.",
        w: { w: 170, h: 40, bot: [15, 20, 90], leader: { path: [[42, 20], [165, 20]], speed: 8 }, time: 14, goal: [{ k: 'follow', min: 4, max: 30, from: 2 }, { k: 'nohit' }] },
        pal: ['run', 'calc'], ops: ['dist'], scripts: ['forever'], vars: ['e', 'v'], varNames: { e: 'error|error', v: 'velocitat|velocidad' },
        prog: 'forever{ run:all,fwd,150 }', sol: 'forever{ calc:e,dist,-,10 calc:v,$e,*,10 run:all,fwd,$v }',
        hint: "És com l'estació de càrrega: error = distància − 10, velocitat = error × 10, i el motor a la variable velocitat.|Es como la estación de carga: error = distancia − 10, velocidad = error × 10, y el motor a la variable velocidad." },
      { k: 'robo', ph: 'repte', q: "Ara el líder <b>s'atura al semàfor</b> i, a cada pista, va a una velocitat diferent. El seguidor no ha de xocar ni quedar-se a més de 30 cm. Si es queda enrere, què canvies?|Ahora el líder <b>se para en el semáforo</b> y, en cada pista, va a una velocidad diferente. El seguidor no tiene que chocar ni quedarse a más de 30 cm. Si se queda atrás, ¿qué cambias?",
        w: { w: 170, h: 40, bot: [15, 20, 90], leader: { path: [[42, 20], [165, 20]], speed: 8, stopAt: 9 }, time: 14, goal: [{ k: 'follow', min: 4, max: 30, from: 2 }, { k: 'nohit' }],
          alts: [{ leader: { path: [[42, 20], [165, 20]], speed: 12, stopAt: 6 } }, { leader: { path: [[42, 20], [165, 20]], speed: 5, stopAt: 11 } }] },
        pal: ['run', 'calc'], ops: ['dist'], scripts: ['forever'], vars: ['e', 'v'], varNames: { e: 'error|error', v: 'velocitat|velocidad' },
        prog: 'forever{ calc:e,dist,-,10 calc:v,$e,*,5 run:all,fwd,$v }', sol: 'forever{ calc:e,dist,-,10 calc:v,$e,*,10 run:all,fwd,$v }',
        hint: "Amb k = 5, quan el líder corre, el seguidor necessita molt d'error i es queda massa lluny. Fes el k més gran.|Con k = 5, cuando el líder corre, el seguidor necesita mucho error y se queda demasiado lejos. Haz el k más grande." },
      { k: 'robo', ph: 'repte', q: "Seguretat: els de darrere han de saber quan frenes. Segueix el líder amb els <b>llums de sota vermells</b> quan la velocitat calculada sigui menor de 60 i <b>verds</b> quan no. Es comprova al segon 4 (verd) i al 11, amb el líder aturat (vermell).|Seguridad: los de detrás tienen que saber cuándo frenas. Sigue al líder con las <b>luces de abajo rojas</b> cuando la velocidad calculada sea menor de 60 y <b>verdes</b> cuando no. Se comprueba en el segundo 4 (verde) y en el 11, con el líder parado (rojo).",
        w: { w: 170, h: 40, bot: [15, 20, 90], leader: { path: [[42, 20], [165, 20]], speed: 8, stopAt: 7 }, time: 12,
          goal: [{ k: 'follow', min: 4, max: 30, from: 2 }, { k: 'nohit' }, { k: 'at', t: 4, under: 'green', why: "Al segon 4 el robot va endavant: els llums de sota han de ser verds.|En el segundo 4 el robot va adelante: las luces de abajo tienen que ser verdes." }, { k: 'at', t: 11, under: 'red', why: "Al segon 11 el robot està aturat darrere el líder: els llums de sota han de ser vermells.|En el segundo 11 el robot está parado detrás del líder: las luces de abajo tienen que ser rojas." }],
          alts: [{ leader: { path: [[42, 20], [165, 20]], speed: 11, stopAt: 5 } }] },
        pal: ['run', 'calc', 'if', 'else', 'under'], ops: ['dist'], scripts: ['forever'], vars: ['e', 'v'], varNames: { e: 'error|error', v: 'velocitat|velocidad' },
        prog: 'forever{ calc:e,dist,-,10 calc:v,$e,*,10 run:all,fwd,$v }', sol: 'forever{ calc:e,dist,-,10 calc:v,$e,*,10 run:all,fwd,$v if:$v<60{ under:all,red } else{ under:all,green } }',
        hint: "Després del motor, afegeix «si velocitat < 60»: llums de sota vermells; «si no»: llums de sota verds.|Después del motor, añade «si velocidad < 60»: luces de abajo rojas; «si no»: luces de abajo verdes." },
      { k: 'robo', ph: 'repte', extra: true, q: "<b>⭐ Repte extra: el líder torna enrere!</b> El seguidor ha de recular per no xocar i continuar entre 4 i 30 cm. Vol estar a 15 cm: si l'error és negatiu, enrere amb velocitat error × −15; si no, endavant amb error × 15.|<b>⭐ Reto extra: ¡el líder vuelve atrás!</b> El seguidor tiene que retroceder para no chocar y seguir entre 4 y 30 cm. Quiere estar a 15 cm: si el error es negativo, atrás con velocidad error × −15; si no, adelante con error × 15.",
        w: { w: 160, h: 40, bot: [30, 20, 90], leader: { path: [[60, 20], [130, 20], [70, 20]], speed: 8 }, time: 18, goal: [{ k: 'follow', min: 4, max: 30, from: 2 }, { k: 'nohit' }] },
        pal: ['run', 'calc', 'if', 'else'], ops: ['dist'], scripts: ['forever'], vars: ['e', 'v'], varNames: { e: 'error|error', v: 'velocitat|velocidad' },
        prog: 'forever{ calc:e,dist,-,15 calc:v,$e,*,15 run:all,fwd,$v }', sol: 'forever{ calc:e,dist,-,15 if:$e<0{ calc:v,$e,*,-15 run:all,back,$v } else{ calc:v,$e,*,15 run:all,fwd,$v } }',
        hint: "Posa un «si error < 0» amb «si no». A dalt: velocitat = error × −15 i motors enrere. A baix: velocitat = error × 15 i motors endavant.|Pon un «si error < 0» con «si no». Arriba: velocidad = error × −15 y motores atrás. Abajo: velocidad = error × 15 y motores adelante." },
      { k: 'rcreate', ph: 'crea', name: 'El meu comboi|Mi convoy',
        q: "El teu robot del comboi! El líder va i s'atura a recollir una caixa. Segueix-lo sense xocar (entre 4 i 30 cm) a les dues pistes i fes que <b>avisi quan frena</b> amb llums, sons o icones. Al segon 3, llums de sota en verd. ⭐ Si vols: que reculi si el líder torna enrere.|¡Tu robot del convoy! El líder va y se para a recoger una caja. Síguelo sin chocar (entre 4 y 30 cm) en las dos pistas y haz que <b>avise cuando frena</b> con luces, sonidos o iconos. En el segundo 3, luces de abajo en verde. ⭐ Si quieres: que retroceda si el líder vuelve atrás.",
        crit: ["Calcula la velocitat amb la distància al líder|Calcula la velocidad con la distancia al líder", "S'atura darrere el líder sense xocar|Se para detrás del líder sin chocar", "Avisa quan frena (al segon 3, llums de sota verds)|Avisa cuando frena (en el segundo 3, luces de abajo verdes)"],
        w: { w: 160, h: 40, bot: [20, 20, 90], leader: { path: [[50, 20], [140, 20]], speed: 8, stopAt: 10 }, time: 16,
          goal: [{ k: 'follow', min: 4, max: 30, from: 2 }, { k: 'nohit' }, { k: 'at', t: 3, under: 'green', why: "Al segon 3 el robot va endavant: els llums de sota han de ser verds.|En el segundo 3 el robot va adelante: las luces de abajo tienen que ser verdes." }],
          alts: [{ leader: { path: [[50, 20], [140, 20]], speed: 10, stopAt: 8 } }] },
        pal: ['run', 'stop', 'calc', 'set', 'change', 'if', 'else', 'car', 'under', 'icon', 'note'], ops: ['dist'], scripts: ['start', 'forever'], vars: ['e', 'v'], varNames: { e: 'error|error', v: 'velocitat|velocidad' },
        check: P => { const k = [], w = l => (l || []).forEach(b => { k.push(b); if (Array.isArray(b.b)) w(b.b); w(b.e); }); w(P.start); w(P.forever); return k.some(b => b.k === 'calc' && ((b.a && b.a.r === 'dist') || (b.y && b.y.r === 'dist'))) ? null : "Funciona, però el repte és seguir amb control proporcional: calcula la velocitat a partir de la distància.|Funciona, pero el reto es seguir con control proporcional: calcula la velocidad a partir de la distancia."; },
        sol: 'forever{ calc:e,dist,-,10 calc:v,$e,*,10 run:all,fwd,$v if:$v<60{ under:all,red } else{ under:all,green } }' },
      { k: 'quiz', ph: 'tanca', q: "Quin sensor fa servir el seguidor per saber on és el líder?|¿Qué sensor usa el seguidor para saber dónde está el líder?",
        opts: ["L'ultrasò (distància en cm)|El ultrasonido (distancia en cm)", "Els sensors de línia|Los sensores de línea", "Els sensors de llum|Los sensores de luz"], a: 0 },
      { k: 'quiz', ph: 'tanca', q: "El líder corre molt i el seguidor es queda massa enrere. Quina és la millor solució?|El líder corre mucho y el seguidor se queda demasiado atrás. ¿Cuál es la mejor solución?",
        opts: ["Fer més gran el multiplicador k|Hacer más grande el multiplicador k", "Posar la velocitat sempre a 255|Poner la velocidad siempre a 255", "Treure el bloc de calcular|Quitar el bloque de calcular"], a: 0,
        ex: "Amb un k més gran, amb menys error ja té velocitat de sobres: el segueix més a prop i continua frenant sol.|Con un k más grande, con menos error ya tiene velocidad de sobra: lo sigue más cerca y sigue frenando solo." },
      { k: 'feel', ph: 'tanca' }
    ] },

  /* ---------- Sessió 4 · Projecte: el cotxe autònom ---------- */
  { id: 'k6-4', t: 'Projecte: el cotxe autònom|Proyecto: el coche autónomo', min: 45, proj: true, badge: 'k_autonom',
    learn: ["Un cotxe autònom combina diversos sensors: la línia per seguir la carretera, l'ultrasò per guardar la distància i la llum per saber si és de nit.|Un coche autónomo combina varios sensores: la línea para seguir la carretera, el ultrasonido para guardar la distancia y la luz para saber si es de noche.",
      "Un programa gran es fa a trossos: primer una part, es prova, i després s'hi afegeix la següent.|Un programa grande se hace a trozos: primero una parte, se prueba, y después se añade la siguiente.",
      "La velocitat calculada amb la distància pot anar als dos motors i també decidir els llums de fre.|La velocidad calculada con la distancia puede ir a los dos motores y también decidir las luces de freno."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "Per seguir una línia negra amb dos sensors (L i R), què ha de fer el robot quan el sensor <b>L</b> veu negre?|Para seguir una línea negra con dos sensores (L y R), ¿qué tiene que hacer el robot cuando el sensor <b>L</b> ve negro?",
        opts: ["Girar cap a l'esquerra: frenar la roda esquerra|Girar hacia la izquierda: frenar la rueda izquierda", "Girar cap a la dreta|Girar hacia la derecha", "Aturar-se del tot|Pararse del todo"], a: 0,
        ex: "Si la línia queda sota el sensor esquerre, la carretera gira a l'esquerra: la roda esquerra va més lenta i el robot hi torna.|Si la línea queda bajo el sensor izquierdo, la carretera gira a la izquierda: la rueda izquierda va más lenta y el robot vuelve a ella." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'lab', title: 'La prova final|La prueba final',
        t: "Gran dia al Lab: la <b>prova del carnet de conduir dels robots</b>! Carretera, un cotxe al davant, un semàfor… i a mitja prova <b>es fa de nit</b>. Faràs el teu cotxe autònom <b>a trossos</b>: carretera, distància, llums de fre i fars.|Gran día en el Lab: ¡la <b>prueba del carnet de conducir de los robots</b>! Carretera, un coche delante, un semáforo… y a mitad de prueba <b>se hace de noche</b>. Harás tu coche autónomo <b>a trozos</b>: carretera, distancia, luces de freno y faros." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Cotxe autònom|Coche autónomo', t: 'Molts sensors, un sol cervell|Muchos sensores, un solo cerebro', anim: 'k6car',
          x: "El cotxe <b>sent</b> amb tres sensors (línia, ultrasò i llum), <b>pensa</b> amb el programa i <b>actua</b> amb els motors i els llums. Els cotxes autònoms de veritat porten càmeres, radars i molts més sensors… i encara necessiten persones que en vigilin la seguretat i decideixin les normes.|El coche <b>siente</b> con tres sensores (línea, ultrasonido y luz), <b>piensa</b> con el programa y <b>actúa</b> con los motores y las luces. Los coches autónomos de verdad llevan cámaras, radares y muchos más sensores… y todavía necesitan personas que vigilen su seguridad y decidan las normas." },
        { k: 'Tros 1|Trozo 1', t: 'La carretera amb velocitat variable|La carretera con velocidad variable',
          robo: { w: { w: 140, h: 90, bot: [50, 73, 90], lines: [{ p: [[100, 73], [110.7, 70.9], [119.8, 64.8], [125.9, 55.7], [128, 45], [125.9, 34.3], [119.8, 25.2], [110.7, 19.1], [100, 17], [40, 17], [29.3, 19.1], [20.2, 25.2], [14.1, 34.3], [12, 45], [14.1, 55.7], [20.2, 64.8], [29.3, 70.9], [40, 73]], closed: true }], time: 22 },
            prog: 'start{ set:vel,150 } forever{ if:L=1{ stop:L run:R,fwd,$vel } else{ if:R=1{ run:L,fwd,$vel stop:R } else{ run:all,fwd,$vel } } }', vars: ['vel'], varNames: { vel: 'velocitat|velocidad' } },
          x: "És el seguidor de línia de la unitat 4, però els motors van a la variable <b>velocitat</b>: després la podrà calcular el control de distància.|Es el seguidor de línea de la unidad 4, pero los motores van a la variable <b>velocidad</b>: después la podrá calcular el control de distancia." },
        { k: 'Tros 2|Trozo 2', t: 'Carretera + distància|Carretera + distancia',
          robo: { w: { w: 140, h: 90, bot: [50, 73, 90], lines: [{ p: [[100, 73], [110.7, 70.9], [119.8, 64.8], [125.9, 55.7], [128, 45], [125.9, 34.3], [119.8, 25.2], [110.7, 19.1], [100, 17], [40, 17], [29.3, 19.1], [20.2, 25.2], [14.1, 34.3], [12, 45], [14.1, 55.7], [20.2, 64.8], [29.3, 70.9], [40, 73]], closed: true }], leader: { path: [[72, 73], [100, 73], [110.7, 70.9], [119.8, 64.8], [125.9, 55.7], [128, 45], [125.9, 34.3], [119.8, 25.2], [110.7, 19.1], [100, 17], [40, 17], [29.3, 19.1], [20.2, 25.2], [14.1, 34.3], [12, 45], [14.1, 55.7], [20.2, 64.8], [29.3, 70.9], [40, 73]], speed: 9, loop: true }, time: 24 },
            prog: 'forever{ calc:e,dist,-,10 calc:v,$e,*,10 if:L=1{ stop:L run:R,fwd,$v } else{ if:R=1{ run:L,fwd,$v stop:R } else{ run:all,fwd,$v } } }', vars: ['e', 'v'], varNames: { e: 'error|error', v: 'velocitat|velocidad' } },
          x: "Ara la velocitat <b>es calcula</b> amb la distància al cotxe del davant. A les corbes, l'ultrasò, que mira recte, de vegades <b>no veu</b> el cotxe del davant i el robot accelera una mica.|Ahora la velocidad <b>se calcula</b> con la distancia al coche de delante. En las curvas, el ultrasonido, que mira recto, a veces <b>no ve</b> el coche de delante y el robot acelera un poco.",
          tip: "Prova cada tros abans d'afegir-ne un altre: si alguna cosa falla, sabràs on buscar.|Prueba cada trozo antes de añadir otro: si algo falla, sabrás dónde buscar." },
        { k: 'Trossos 3 i 4|Trozos 3 y 4', t: 'Llums de fre i fars de nit|Luces de freno y faros de noche', anim: 'k6lead',
          x: "<b>Llums de fre</b>: si la velocitat calculada és menor de 60, llums de sota vermells; si no, verds. <b>Fars</b>: si la llum és menor de 100 (de nit ~25, de dia ~260), llums del cotxe blancs; si no, apagats. Són dos «si» més al final del «per sempre».|<b>Luces de freno</b>: si la velocidad calculada es menor de 60, luces de abajo rojas; si no, verdes. <b>Faros</b>: si la luz es menor de 100 (de noche ~25, de día ~260), luces del coche blancas; si no, apagadas. Son dos «si» más al final del «para siempre»." }
      ] },
      { k: 'seq', ph: 'mans', q: "Ordena el pla de treball del projecte, com ho faria un equip d'enginyeria.|Ordena el plan de trabajo del proyecto, como lo haría un equipo de ingeniería.",
        items: ["Seguir la carretera amb una variable de velocitat i provar-ho|Seguir la carretera con una variable de velocidad y probarlo", "Calcular la velocitat amb la distància al cotxe del davant i provar-ho|Calcular la velocidad con la distancia al coche de delante y probarlo", "Afegir els llums de fre i provar-ho al semàfor|Añadir las luces de freno y probarlo en el semáforo", "Afegir els fars de nit amb el sensor de llum|Añadir los faros de noche con el sensor de luz", "Provar-ho tot a totes les pistes i passar-ho al Maqueen de veritat|Probarlo todo en todas las pistas y pasarlo al Maqueen de verdad"],
        ex: "A trossos i provant cada tros: si l'últim pas falla, saps que el problema és en el que acabes d'afegir.|A trozos y probando cada trozo: si el último paso falla, sabes que el problema está en lo que acabas de añadir." },
      { k: 'quiz', ph: 'mans', q: "Quin sensor fa servir el cotxe per a cada feina? Tria l'opció bona.|¿Qué sensor usa el coche para cada trabajo? Elige la opción correcta.",
        opts: ["Carretera → línia L i R · Distància → ultrasò · Nit → llum|Carretera → línea L y R · Distancia → ultrasonido · Noche → luz", "Carretera → llum · Distància → línia · Nit → ultrasò|Carretera → luz · Distancia → línea · Noche → ultrasonido", "Carretera → ultrasò · Distància → llum · Nit → línia|Carretera → ultrasonido · Distancia → luz · Noche → línea"], a: 0 },
      { k: 'rspot', ph: 'investiga', q: "En aquest cotxe, els llums de fre s'encenen quan va <b>de pressa</b> i s'apaguen quan frena: tot a l'inrevés! Pots executar-lo. <b>Toca el bloc que cal canviar.</b>|En este coche, las luces de freno se encienden cuando va <b>deprisa</b> y se apagan cuando frena: ¡todo al revés! Puedes ejecutarlo. <b>Toca el bloque que hay que cambiar.</b>",
        w: { w: 170, h: 40, bot: [15, 20, 90], leader: { path: [[42, 20], [165, 20]], speed: 8, stopAt: 7 }, time: 12 },
        prog: 'forever{ calc:e,dist,-,10 calc:v,$e,*,10 run:all,fwd,$v if:$v>60!{ under:all,red } else{ under:all,green } }', scripts: ['forever'], vars: ['e', 'v'], varNames: { e: 'error|error', v: 'velocitat|velocidad' },
        yes: "Exacte! La condició ha de ser «velocitat < 60»: vermell quan va lent o aturat.|¡Exacto! La condición tiene que ser «velocidad < 60»: rojo cuando va lento o parado.",
        ex: "És la condició del «si»: amb «velocitat > 60» posa vermell quan va de pressa. Ha de ser «velocitat < 60».|Es la condición del «si»: con «velocidad > 60» pone rojo cuando va deprisa. Tiene que ser «velocidad < 60»." },
      { k: 'quiz', ph: 'investiga', q: "A les corbes, de vegades el cotxe accelera de cop encara que el del davant sigui a prop. Per què?|En las curvas, a veces el coche acelera de golpe aunque el de delante esté cerca. ¿Por qué?",
        opts: ["L'ultrasò mira recte i a la corba no veu el cotxe del davant: marca molta distància|El ultrasonido mira recto y en la curva no ve el coche de delante: marca mucha distancia", "El motor s'ha espatllat|El motor se ha estropeado", "El sensor de línia mesura la distància|El sensor de línea mide la distancia"], a: 0,
        ex: "El con de l'ultrasò és estret: si no rep l'eco, marca 500 i l'error es fa enorme. A les corbes, millor no anar massa de pressa.|El cono del ultrasonido es estrecho: si no recibe el eco, marca 500 y el error se hace enorme. En las curvas, mejor no ir demasiado deprisa." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Cotxe autònom humà! Braços endavant com a ultrasò i ulls a terra com a sensors de línia. «Semàfor!»: frena a poc a poc i fes «piiip» de llum vermella. «Nit!»: fars amb les mans.|¡Coche autónomo humano! Brazos adelante como ultrasonido y ojos al suelo como sensores de línea. «¡Semáforo!»: frena poco a poco y haz «piiip» de luz roja. «¡Noche!»: faros con las manos." },
      { k: 'robo', ph: 'repte', q: "<b>Tros 1: la carretera.</b> Fes que el cotxe faci una volta sencera al circuit (passant pels 4 punts) seguint la línia amb dos sensors. Els motors han d'anar a la variable <b>velocitat</b>, que comença a 150.|<b>Trozo 1: la carretera.</b> Haz que el coche dé una vuelta entera al circuito (pasando por los 4 puntos) siguiendo la línea con dos sensores. Los motores tienen que ir a la variable <b>velocidad</b>, que empieza en 150.",
        w: { w: 140, h: 90, bot: [50, 73, 90], lines: [{ p: [[100, 73], [110.7, 70.9], [119.8, 64.8], [125.9, 55.7], [128, 45], [125.9, 34.3], [119.8, 25.2], [110.7, 19.1], [100, 17], [40, 17], [29.3, 19.1], [20.2, 25.2], [14.1, 34.3], [12, 45], [14.1, 55.7], [20.2, 64.8], [29.3, 70.9], [40, 73]], closed: true }], time: 25,
          goal: [{ k: 'cps', pts: [[126, 45], [70, 17], [14, 45], [62, 73]], r: 8 }] },
        pal: ['run', 'stop', 'set', 'if', 'else'], ops: ['L', 'R'], scripts: ['start', 'forever'], vars: ['vel'], varNames: { vel: 'velocitat|velocidad' },
        prog: 'start{ set:vel,150 }', sol: 'start{ set:vel,150 } forever{ if:L=1{ stop:L run:R,fwd,$vel } else{ if:R=1{ run:L,fwd,$vel stop:R } else{ run:all,fwd,$vel } } }',
        hint: "«Si L = 1»: atura el motor esquerre i el dret a velocitat. «Si no, si R = 1»: l'esquerre a velocitat i atura el dret. «Si no»: tots dos a velocitat.|«Si L = 1»: para el motor izquierdo y el derecho a velocidad. «Si no, si R = 1»: el izquierdo a velocidad y para el derecho. «Si no»: los dos a velocidad." },
      { k: 'robo', ph: 'repte', q: "<b>Tros 2: guarda la distància.</b> Ara hi ha un cotxe al davant que fa voltes. Calcula la velocitat amb la distància (error = distància − 10, velocitat = error × 10) i fes-la servir al seguidor de línia. Ha de seguir-lo entre 4 i 30 cm sense xocar.|<b>Trozo 2: guarda la distancia.</b> Ahora hay un coche delante que da vueltas. Calcula la velocidad con la distancia (error = distancia − 10, velocidad = error × 10) y úsala en el seguidor de línea. Tiene que seguirlo entre 4 y 30 cm sin chocar.",
        w: { w: 140, h: 90, bot: [50, 73, 90], lines: [{ p: [[100, 73], [110.7, 70.9], [119.8, 64.8], [125.9, 55.7], [128, 45], [125.9, 34.3], [119.8, 25.2], [110.7, 19.1], [100, 17], [40, 17], [29.3, 19.1], [20.2, 25.2], [14.1, 34.3], [12, 45], [14.1, 55.7], [20.2, 64.8], [29.3, 70.9], [40, 73]], closed: true }],
          leader: { path: [[72, 73], [100, 73], [110.7, 70.9], [119.8, 64.8], [125.9, 55.7], [128, 45], [125.9, 34.3], [119.8, 25.2], [110.7, 19.1], [100, 17], [40, 17], [29.3, 19.1], [20.2, 25.2], [14.1, 34.3], [12, 45], [14.1, 55.7], [20.2, 64.8], [29.3, 70.9], [40, 73]], speed: 9, loop: true }, time: 25,
          goal: [{ k: 'follow', min: 4, max: 30, from: 3 }, { k: 'nohit' }] },
        pal: ['run', 'stop', 'calc', 'if', 'else'], ops: ['dist', 'L', 'R'], scripts: ['forever'], vars: ['e', 'v'], varNames: { e: 'error|error', v: 'velocitat|velocidad' },
        prog: 'forever{ if:L=1{ stop:L run:R,fwd,150 } else{ if:R=1{ run:L,fwd,150 stop:R } else{ run:all,fwd,150 } } }',
        sol: 'forever{ calc:e,dist,-,10 calc:v,$e,*,10 if:L=1{ stop:L run:R,fwd,$v } else{ if:R=1{ run:L,fwd,$v stop:R } else{ run:all,fwd,$v } } }',
        hint: "Posa els dos blocs de calcular al principi del «per sempre» i canvia el 150 de tots els motors per la variable velocitat.|Pon los dos bloques de calcular al principio del «para siempre» y cambia el 150 de todos los motores por la variable velocidad." },
      { k: 'robo', ph: 'repte', q: "<b>Tros 3: el semàfor.</b> El cotxe del davant s'atura al semàfor. El teu para darrere sense xocar. El programa ja té el «si velocitat < 60» buit: posa-hi els <b>llums de sota vermells</b> i, al «si no», <b>verds</b>. Es comprova al segon 4 (verd) i al 21 (vermell).|<b>Trozo 3: el semáforo.</b> El coche de delante se para en el semáforo. El tuyo para detrás sin chocar. El programa ya tiene el «si velocidad < 60» vacío: pon las <b>luces de abajo rojas</b> y, en el «si no», <b>verdes</b>. Se comprueba en el segundo 4 (verde) y en el 21 (rojo).",
        w: { w: 140, h: 90, bot: [50, 73, 90], lines: [{ p: [[100, 73], [110.7, 70.9], [119.8, 64.8], [125.9, 55.7], [128, 45], [125.9, 34.3], [119.8, 25.2], [110.7, 19.1], [100, 17], [40, 17], [29.3, 19.1], [20.2, 25.2], [14.1, 34.3], [12, 45], [14.1, 55.7], [20.2, 64.8], [29.3, 70.9], [40, 73]], closed: true }],
          leader: { path: [[72, 73], [100, 73], [110.7, 70.9], [119.8, 64.8], [125.9, 55.7], [128, 45], [125.9, 34.3], [119.8, 25.2], [110.7, 19.1], [100, 17], [40, 17], [29.3, 19.1], [20.2, 25.2], [14.1, 34.3], [12, 45], [14.1, 55.7], [20.2, 64.8], [29.3, 70.9], [40, 73]], speed: 9, loop: true, stopAt: 16 }, time: 22,
          goal: [{ k: 'follow', min: 4, max: 30, from: 3 }, { k: 'nohit' }, { k: 'at', t: 4, under: 'green', why: "Al segon 4 el cotxe circula: els llums de sota han de ser verds.|En el segundo 4 el coche circula: las luces de abajo tienen que ser verdes." }, { k: 'at', t: 21, under: 'red', why: "Al segon 21 el cotxe és aturat al semàfor: els llums de sota han de ser vermells.|En el segundo 21 el coche está parado en el semáforo: las luces de abajo tienen que ser rojas." }] },
        pal: ['run', 'stop', 'calc', 'if', 'else', 'under'], ops: ['dist', 'L', 'R'], scripts: ['forever'], vars: ['e', 'v'], varNames: { e: 'error|error', v: 'velocitat|velocidad' },
        prog: 'forever{ calc:e,dist,-,10 calc:v,$e,*,10 if:L=1{ stop:L run:R,fwd,$v } else{ if:R=1{ run:L,fwd,$v stop:R } else{ run:all,fwd,$v } } if:$v<60{ } else{ } }',
        sol: 'forever{ calc:e,dist,-,10 calc:v,$e,*,10 if:L=1{ stop:L run:R,fwd,$v } else{ if:R=1{ run:L,fwd,$v stop:R } else{ run:all,fwd,$v } } if:$v<60{ under:all,red } else{ under:all,green } }',
        hint: "Dins del «si velocitat < 60»: llums de sota vermells. Al «si no»: llums de sota verds.|Dentro del «si velocidad < 60»: luces de abajo rojas. En el «si no»: luces de abajo verdes." },
      { k: 'rcreate', ph: 'crea', name: 'El meu cotxe autònom|Mi coche autónomo',
        q: "<b>La prova del carnet!</b> El programa del tros 3 ja hi és. Afegeix-hi els <b>fars</b>: quan <b>es fa de nit</b> (segon 8), llums del cotxe <b>blancs</b> amb el sensor de llum (es comprova al segon 12). Ha de funcionar a les dues pistes. Pots afegir-hi el que vulguis: icones, sons…|<b>¡La prueba del carnet!</b> El programa del trozo 3 ya está. Añádele los <b>faros</b>: cuando <b>se hace de noche</b> (segundo 8), luces del coche <b>blancas</b> con el sensor de luz (se comprueba en el segundo 12). Tiene que funcionar en las dos pistas. Puedes añadir lo que quieras: iconos, sonidos…",
        crit: ["Segueix la carretera i el cotxe del davant sense xocar|Sigue la carretera y el coche de delante sin chocar", "Llums de fre: vermells quan frena, verds quan circula|Luces de freno: rojas cuando frena, verdes cuando circula", "Fars blancs de nit amb el sensor de llum|Faros blancos de noche con el sensor de luz", "Funciona a les dues pistes|Funciona en las dos pistas"],
        w: { w: 140, h: 90, bot: [50, 73, 90], lines: [{ p: [[100, 73], [110.7, 70.9], [119.8, 64.8], [125.9, 55.7], [128, 45], [125.9, 34.3], [119.8, 25.2], [110.7, 19.1], [100, 17], [40, 17], [29.3, 19.1], [20.2, 25.2], [14.1, 34.3], [12, 45], [14.1, 55.7], [20.2, 64.8], [29.3, 70.9], [40, 73]], closed: true }],
          leader: { path: [[72, 73], [100, 73], [110.7, 70.9], [119.8, 64.8], [125.9, 55.7], [128, 45], [125.9, 34.3], [119.8, 25.2], [110.7, 19.1], [100, 17], [40, 17], [29.3, 19.1], [20.2, 25.2], [14.1, 34.3], [12, 45], [14.1, 55.7], [20.2, 64.8], [29.3, 70.9], [40, 73]], speed: 9, loop: true, stopAt: 16 }, env: [{ t: 8, dark: true }], time: 22,
          goal: [{ k: 'follow', min: 4, max: 30, from: 3 }, { k: 'nohit' }, { k: 'at', t: 4, under: 'green', why: "Al segon 4 el cotxe circula: els llums de sota han de ser verds.|En el segundo 4 el coche circula: las luces de abajo tienen que ser verdes." }, { k: 'at', t: 21, under: 'red', why: "Al segon 21 el cotxe és aturat al semàfor: els llums de sota han de ser vermells.|En el segundo 21 el coche está parado en el semáforo: las luces de abajo tienen que ser rojas." }, { k: 'at', t: 12, car: 'white', why: "Al segon 12 ja és de nit: els fars (llums del cotxe) han de ser blancs.|En el segundo 12 ya es de noche: los faros (luces del coche) tienen que ser blancos." }],
          alts: [{ leader: { path: [[72, 73], [100, 73], [110.7, 70.9], [119.8, 64.8], [125.9, 55.7], [128, 45], [125.9, 34.3], [119.8, 25.2], [110.7, 19.1], [100, 17], [40, 17], [29.3, 19.1], [20.2, 25.2], [14.1, 34.3], [12, 45], [14.1, 55.7], [20.2, 64.8], [29.3, 70.9], [40, 73]], speed: 8, loop: true, stopAt: 17 }, env: [{ t: 6, dark: true }] }] },
        pal: ['run', 'stop', 'calc', 'set', 'change', 'if', 'else', 'and', 'under', 'car', 'icon', 'note'], ops: ['dist', 'L', 'R', 'lL', 'lR'], scripts: ['start', 'forever'], vars: ['e', 'v'], varNames: { e: 'error|error', v: 'velocitat|velocidad' },
        check: P => { const k = [], w = l => (l || []).forEach(b => { k.push(b); if (Array.isArray(b.b)) w(b.b); w(b.e); }); w(P.start); w(P.forever); return k.some(b => b.k === 'calc' && ((b.a && b.a.r === 'dist') || (b.y && b.y.r === 'dist'))) ? null : "Funciona, però el cotxe ha de calcular la velocitat amb la distància al cotxe del davant.|Funciona, pero el coche tiene que calcular la velocidad con la distancia al coche de delante."; },
        prog: 'forever{ calc:e,dist,-,10 calc:v,$e,*,10 if:L=1{ stop:L run:R,fwd,$v } else{ if:R=1{ run:L,fwd,$v stop:R } else{ run:all,fwd,$v } } if:$v<60{ under:all,red } else{ under:all,green } }',
        sol: 'forever{ calc:e,dist,-,10 calc:v,$e,*,10 if:L=1{ stop:L run:R,fwd,$v } else{ if:R=1{ run:L,fwd,$v stop:R } else{ run:all,fwd,$v } } if:$v<60{ under:all,red } else{ under:all,green } if:lL<100{ car:all,white } else{ car:all,black } }' },
      { k: 'quiz', ph: 'tanca', q: "Per què és bona idea fer un programa gran <b>a trossos</b>?|¿Por qué es buena idea hacer un programa grande <b>a trozos</b>?",
        opts: ["Perquè si alguna cosa falla, saps que és en l'últim tros que has afegit|Porque si algo falla, sabes que está en el último trozo que has añadido", "Perquè el robot va més de pressa|Porque el robot va más deprisa", "Perquè així no cal provar-lo|Porque así no hace falta probarlo"], a: 0 },
      { k: 'quiz', ph: 'tanca', q: "Els cotxes autònoms de veritat fan el mateix que el teu Maqueen, però amb molts més sensors. Què continua sent important?|Los coches autónomos de verdad hacen lo mismo que tu Maqueen, pero con muchos más sensores. ¿Qué sigue siendo importante?",
        opts: ["Provar-los molt i que hi hagi persones que en vigilin la seguretat|Probarlos mucho y que haya personas que vigilen su seguridad", "Res: com que són robots, no s'equivoquen mai|Nada: como son robots, no se equivocan nunca", "Que vagin sempre a la velocitat màxima|Que vayan siempre a la velocidad máxima"], a: 0,
        ex: "Els sensors poden fallar (com l'ultrasò a les corbes). Per això els proven en moltes situacions, i hi ha normes i persones responsables de la seguretat.|Los sensores pueden fallar (como el ultrasonido en las curvas). Por eso se prueban en muchas situaciones, y hay normas y personas responsables de la seguridad." },
      { k: 'feel', ph: 'tanca' }
    ] }
] };
